Unit tests for `sort_list`:

```python
import unittest

def sort_list(num_list):
    return sorted(num_list)

class TestSortList(unittest.TestCase):
    def test_empty_list(self):
        self.assertEqual(sort_list([]), [])

    def test_single_element(self):
        self.assertEqual(sort_list([1]), [1])

    def test_already_sorted(self):
        self.assertEqual(sort_list([1, 2, 3]), [1, 2, 3])

    def test_reverse_sorted(self):
        self.assertEqual(sort_list([3, 2, 1]), [1, 2, 3])

    def test_unsorted(self):
        self.assertEqual(sort_list([5, 1, 3, 2, 4]), [1, 2, 3, 4, 5])

    def test_negative_numbers(self):
        self.assertEqual(sort_list([-1, -3, 2, 0]), [-3, -1, 0, 2])

    def test_duplicate_elements(self):
        self.assertEqual(sort_list([2, 1, 2, 1]), [1, 1, 2, 2])

if __name__ == '__main__':
    unittest.main()
```

